def merge_duplicate_totp_devices(apps, schema_editor):
    """(user, secret) が重複した TOTP デバイスを 1 件にまとめる

    一意制約を付ける前に、残す 1 件へ最も新しい使用済み時間枠と有効状態を引き継ぎ、残りを削除する。
    """
    TOTPDevice = apps.get_model("custom_auth", "TOTPDevice")
    duplicates = (
        TOTPDevice.objects.values("user_id", "secret")
        .annotate(count=models.Count("id"))
        .filter(count__gt=1)
    )
    for row in duplicates:
        devices = list(TOTPDevice.objects.filter(user_id=row["user_id"], secret=row["secret"]).order_by("id"))
        keep, others = devices[0], devices[1:]
        steps = [device.last_used_step for device in devices if device.last_used_step is not None]
        keep.last_used_step = max(steps) if steps else None
        keep.is_active = any(device.is_active for device in devices)
        keep.save(update_fields=["last_used_step", "is_active"])
        TOTPDevice.objects.filter(id__in=[device.id for device in others]).delete()


